74	// TestCLIInvalidUnicodeRejectsAllCommands 记录文件含无效 Unicode 文字时，
75	// 所有需要打开文件的命令都在读取阶段以退出码 2 拒绝：标准输出不出现核对
76	// 结果、登记成功或免修已保存的反馈，标准错误明确指出记录文件包含无效的
77	// Unicode 文字，原文件内容保持不变。
78	func TestCLIInvalidUnicodeRejectsAllCommands(t *testing.T) {
79		hi, lo := uesc("D800"), uesc("DC00")
