467		out, _, code = runCLI(t, file, "check", "s2")
468		if code != 0 || !strings.Contains(out, "总学分：0") ||
469			!strings.Contains(out, "未满足要求：[r1]") || strings.Contains(out, "通过修读") {
470			t.Fatalf("s2 不应因 s1 的同号通过拿到学分，code=%d out=%q", code, out)
471		}
472		if out, _, _ := runCLI(t, file, "show", "s2"); !strings.Contains(out, "结果：选课") {
473			t.Fatalf("s2 的同号修读应保持选课，out=%q", out)
474		}
475	
476		// s2 随后提交未通过：退出码 0，s2 仍为 0 学分、要求未满足。
477		if _, errText, code := runCLI(t, file, "fail", "s2", "e1"); code != 0 {
478			t.Fatalf("s2 首次提交未通过应成功且退出码 0，code=%d err=%q", code, errText)
479		}
480		out, _, code = runCLI(t, file, "check", "s2")
481		if code != 0 || !strings.Contains(out, "总学分：0") ||
482			!strings.Contains(out, "未满足要求：[r1]") {
483			t.Fatalf("s2 未通过后应仍为 0 学分且要求未满足，code=%d out=%q", code, out)
484		}
485		if out, _, _ := runCLI(t, file, "show", "s2"); !strings.Contains(out, "结果：未通过") {
486			t.Fatalf("s2 的修读应记录为未通过，out=%q", out)
487		}
488		// s1 原来的通过结果、学分与来源均保持不变。
489		out, _, code = runCLI(t, file, "check", "s1")
490		if code != 0 || !strings.Contains(out, "总学分：4") ||
491			!strings.Contains(out, "来源为通过修读 e1") {
492			t.Fatalf("s2 提交未通过不应影响 s1 原有的通过结果，code=%d out=%q", code, out)
493		}
494		if out, _, _ := runCLI(t, file, "show", "s1"); !strings.Contains(out, "结果：通过") {
495			t.Fatalf("s1 的修读应保持通过，out=%q", out)
496		}
497	
498		// 两人结果不同应分别被接受：各自重复提交相同结果幂等成功（退出码 0），
499		// 不能被误判为同一次修读的结果冲突；状态不变。
500		if _, errText, code := runCLI(t, file, "pass", "s1", "e1"); code != 0 {
501			t.Fatalf("s1 重复提交通过应幂等成功，code=%d err=%q", code, errText)
502		}
503		if _, errText, code := runCLI(t, file, "fail", "s2", "e1"); code != 0 {
504			t.Fatalf("s2 重复提交未通过应幂等成功，code=%d err=%q", code, errText)
505		}
506		out, _, _ = runCLI(t, file, "check", "s1")
507		if !strings.Contains(out, "总学分：4") || !strings.Contains(out, "来源为通过修读 e1") {
508			t.Fatalf("幂等重复后 s1 结果应不变，out=%q", out)
509		}
510		out, _, _ = runCLI(t, file, "check", "s2")
511		if !strings.Contains(out, "总学分：0") || !strings.Contains(out, "未满足要求：[r1]") {
512			t.Fatalf("幂等重复后 s2 结果应不变，out=%q", out)
513		}
514	
515		// 各自把本人这份修读改成另一结果：仍按现有规则拒绝（退出码 1）、保留原结果，
516		// 另一名学生的同号修读保持原样。
517		if _, errText, code := runCLI(t, file, "fail", "s1", "e1"); code != 1 {
518			t.Fatalf("s1 通过后改提未通过应拒绝且退出码 1，code=%d err=%q", code, errText)
519		}
520		if _, errText, code := runCLI(t, file, "pass", "s2", "e1"); code != 1 {
521			t.Fatalf("s2 未通过后改提通过应拒绝且退出码 1，code=%d err=%q", code, errText)
522		}
523		if out, _, _ := runCLI(t, file, "show", "s1"); !strings.Contains(out, "结果：通过") {
524			t.Fatalf("被拒绝后 s1 应保留原通过结果，out=%q", out)
525		}
526		if out, _, _ := runCLI(t, file, "show", "s2"); !strings.Contains(out, "结果：未通过") {
527			t.Fatalf("被拒绝后 s2 应保留原未通过结果，out=%q", out)
528		}
529		out, _, _ = runCLI(t, file, "check", "s1")
530		if !strings.Contains(out, "总学分：4") || !strings.Contains(out, "来源为通过修读 e1") {
531			t.Fatalf("改结果被拒后 s1 学分与来源应不变，out=%q", out)
532		}
533		out, _, _ = runCLI(t, file, "check", "s2")
534		if !strings.Contains(out, "总学分：0") || !strings.Contains(out, "未满足要求：[r1]") {
535			t.Fatalf("改结果被拒后 s2 应仍为 0 学分未满足，out=%q", out)
536		}
537	}
538	
539	// TestCLISharedEnrollmentResultOwnershipReversed 交换两名学生的登记与处理顺序：
540	// 先 s2 未通过、再 s1 通过，归属结论必须一致，不依赖先登记或先处理谁。
541	func TestCLISharedEnrollmentResultOwnershipReversed(t *testing.T) {
542		file := filepath.Join(t.TempDir(), "records.json")
543		// 先登记 s2，再登记 s1。
544		for _, st := range [][]string{
545			{"student", "s2"},
546			{"student", "s1"},
547			{"course", "c1", "高等数学", "4"},
548			{"req", "s2", "r1", "c1"},
549			{"req", "s1", "r1", "c1"},
550			{"enroll", "s2", "r1", "2024春", "e1"},
551			{"enroll", "s1", "r1", "2024春", "e1"},
552		} {
553			if _, errText, code := runCLI(t, file, st...); code != 0 {
554				t.Fatalf("步骤 %v 应成功，code=%d err=%q", st, code, errText)
555			}
556		}
557	
558		if _, _, code := runCLI(t, file, "fail", "s2", "e1"); code != 0 {
559			t.Fatal("先处理的 s2 提交未通过应成功")
560		}
561		if _, _, code := runCLI(t, file, "pass", "s1", "e1"); code != 0 {
562			t.Fatal("后处理的 s1 提交通过应成功")
563		}
564	
565		out, _, code := runCLI(t, file, "check", "s1")
566		if code != 0 || !strings.Contains(out, "总学分：4") ||
567			!strings.Contains(out, "来源为通过修读 e1") {
568			t.Fatalf("s1 应由本人 e1 通过获得 4 学分，code=%d out=%q", code, out)
569		}
570		if out, _, _ := runCLI(t, file, "show", "s1"); !strings.Contains(out, "结果：通过") {
571			t.Fatalf("s1 的修读应为通过，out=%q", out)
572		}
573		out, _, code = runCLI(t, file, "check", "s2")
574		if code != 0 || !strings.Contains(out, "总学分：0") ||
575			!strings.Contains(out, "未满足要求：[r1]") {
576			t.Fatalf("s2 应仍为 0 学分且要求未满足，code=%d out=%q", code, out)
577		}
578		if out, _, _ := runCLI(t, file, "show", "s2"); !strings.Contains(out, "结果：未通过") {
579			t.Fatalf("s2 的修读应为未通过，out=%q", out)
580		}
581	}
582	
583	// TestCLISubmitResultUnknownEnrollmentUnderOtherStudent 修读编号只存在于 s1 名下时，
584	// 用 s2 的名义提交结果必须明确报告 s2 名下没有该修读、退出码 1，不能借用 s1 的
585	// 修读，也不能为 s2 补出新记录；拒绝后两人的状态、要求与总学分与提交前一致，
586	// 记录文件也不应被这次拒绝改写。
587	func TestCLISubmitResultUnknownEnrollmentUnderOtherStudent(t *testing.T) {
588		file := filepath.Join(t.TempDir(), "records.json")
589		for _, st := range [][]string{
590			{"student", "s1"},
591			{"student", "s2"},
592			{"course", "c1", "高等数学", "4"},
593			{"req", "s1", "r1", "c1"},
594			{"enroll", "s1", "r1", "2024春", "e1"},
595		} {
596			if _, errText, code := runCLI(t, file, st...); code != 0 {
597				t.Fatalf("步骤 %v 应成功，code=%d err=%q", st, code, errText)
598			}
599		}
600		before, err := os.ReadFile(file)
601		if err != nil {
602			t.Fatal(err)
603		}
604	
605		// 用 s2 的编号提交只属于 s1 的修读结果：退出码 1，信息点名 s2 与 e1。
606		out, errText, code := runCLI(t, file, "pass", "s2", "e1")
607		if code != 1 {
608			t.Fatalf("借名提交应拒绝且退出码 1，code=%d out=%q err=%q", code, out, errText)
609		}
610		if !strings.Contains(errText, "s2") || !strings.Contains(errText, "e1") ||
611			!strings.Contains(errText, "不存在") {
612			t.Fatalf("应明确报告学生 s2 名下不存在修读 e1，out=%q err=%q", out, errText)
613		}
614	
615		// 被拒绝的请求不应改写记录文件。
616		after, err := os.ReadFile(file)
617		if err != nil {
618			t.Fatal(err)
619		}
620		if string(before) != string(after) {
621			t.Fatalf("拒绝后记录文件不应变化\nbefore=%s\nafter=%s", before, after)
622		}
623	
624		// 不能借用 s1 的修读：s1 的 e1 仍是选课、0 学分、要求未满足。
625		if out, _, _ := runCLI(t, file, "show", "s1"); !strings.Contains(out, "结果：选课") {
626			t.Fatalf("s1 的修读不应被借名提交改写，out=%q", out)
627		}
628		out, _, code = runCLI(t, file, "check", "s1")
629		if code != 0 || !strings.Contains(out, "总学分：0") ||
630			!strings.Contains(out, "未满足要求：[r1]") {
631			t.Fatalf("s1 拒绝后应与提交前一致（0 学分未满足），code=%d out=%q", code, out)
632		}
633		// 不能为 s2 补出一条新记录：show 中没有任何修读，核对总学分 0。
634		if out, _, _ := runCLI(t, file, "show", "s2"); strings.Contains(out, "修读 e1") {
635			t.Fatalf("不应在 s2 名下补出修读记录，out=%q", out)
636		}
637		out, _, code = runCLI(t, file, "check", "s2")
638		if code != 0 || !strings.Contains(out, "总学分：0") {
639			t.Fatalf("s2 不应因拒绝产生任何变化，code=%d out=%q", code, out)
