			args, code, stdout.String(), lastBytes(stderr.String(), 40))
	}
	got, _ := os.ReadFile(f)
	if string(got) == content {
		fmt.Println("FILE UNCHANGED: OK")
	} else {
		fmt.Println("FILE CHANGED!")
	}
