		t.Fatalf("错误应同时说明开放状态为空与缺少编号，得到：%v", err)
	}
	if got, readErr := os.ReadFile(path); readErr != nil || string(got) != string(raw) {
		t.Fatalf("拒绝读取不得改写原文件，readErr=%v", readErr)
